package com.opensocket.aievent.core.analytics.runtime;
import org.springframework.beans.factory.DisposableBean;import org.springframework.beans.factory.InitializingBean;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.scheduling.TaskScheduler;import org.springframework.stereotype.Component;import com.opensocket.aievent.core.analytics.EnterpriseAnalyticsProjectionWorker;import com.opensocket.aievent.core.configuration.runtime.DynamicFixedDelayTask;
@Component public final class AnalyticsDynamicScheduler implements InitializingBean,DisposableBean {private final DynamicFixedDelayTask task;public AnalyticsDynamicScheduler(AnalyticsRuntimeConfigurationView runtime,EnterpriseAnalyticsProjectionWorker worker,@Qualifier("projectionOperationalScheduler") TaskScheduler scheduler){task=new DynamicFixedDelayTask(scheduler,"enterprise-analytics-projection",worker::projectPending,runtime::pollDelay);}public void afterPropertiesSet(){task.start();}public void destroy(){task.stop();}}
